    assert(solution.braceExpansionII("a") == vector<int>{'a'});
    assert(solution.braceExpansionII("{a,bc,def}") == vector<int>{'a', 'bc', 'def'});
    assert(solution.braceExpansionII("a{b{c,d},e{f,g}}") == vector<int>{'abc', 'abd', 'aef', 'aeg'});
    assert(solution.braceExpansionII("{a,b,c}") == vector<int>{'a', 'b', 'c'});
    assert(solution.braceExpansionII("{a,b}c") == vector<int>{'ac', 'bc'});
    assert(solution.braceExpansionII("{abc}") == vector<int>{'abc'});
    assert(solution.braceExpansionII("a{b,c,d}e") == vector<int>{'abe', 'ace', 'ade'});
