    assert(solution.braceExpansionII("a{b,c}d") == vector<int>{'abd', 'acd'});
    assert(solution.braceExpansionII("{a,b}{c,{d,e}}") == vector<int>{'ac', 'ad', 'ae', 'bc', 'bd', 'be'});
